INSERT INTO `bh_bar` VALUES (7,'BeetleCraft','<u>BeetleCraft</u> - это:n n~ место силы, n~ место, где обретаются лучшие друзья, n~ место, где можно быть любым и ни в чем себе не отказыватьn~ место, где можно попробовать лучшее пиво и необычные шавухи.nn<b><u>По средам Пилс от Нормы всего по 100 рублей за кружку.</u>nчтобы получить скидку, покажите это сообщение на телефоне</b>nn<i>Отправьте сюда фото пива</i>','https://go.2gis.com/tvi1b','ул. Московская, 2','Ежедневно с 11 до 23 часов',3,'1','https://www.instagram.com/beetle.craft?igsh=MzRlODBiNWFlZA=='),(4,'BBQ Bar','<u>BBQ Bar</u> - это место, где можно вкусно поесть, попить, послушать музыку и просто хорошо провести время. Уже 9 лет мы крутим винил, радуем своих гостей вкусным вином, сочными стейками, широким ассортиментом пенного и фирменными бургерами. Место отлично подходит как для веселых встреч с друзьями, теплых семейных обедов и ужинов, а также для романтического свидания со своей второй половинкой. nn<b><u>По понедельникам действует акция на настойки - ДВЕ ПО ЦЕНЕ ОДНОЙ.</u>nчтобы получить скидку, покажите это сообщение на телефоне</b>nn<i>Отправьте сюда фото из бара</i>','https://go.2gis.com/8s3u9','ул. ​Московская, 63','Ежедневно c 11:00 до 24:00',1,'1','https://www.instagram.com/bbqbarpnz?igsh=MzRlODBiNWFlZA=='),(6,'БлинОК','<u>Блин-бар Блин\'ОК</u> - предлагает к Вашему вниманию блюда русской кухни в популярном новом формате. Начинки разнообразного вкусового ассортимента, молочные коктейли, вкусозавораживающие лимонады и ароматный кофе.nn<b><u>По вторникам действует скидка на все блины 15%.</u>nчтобы получить скидку, покажите это сообщение на телефоне</b>nn<i>Отправьте сюда фото блина</i>','https://yandex.ru/maps/-/CDBq6MZQ','ул. Карла Маркса, 30​','Ежедневно с 9:00 до 21:00',2,'1','https://vk.com/club223623599'),(7,'Malevichi','<u>Ресторан-бар \"Malevichi\"</u>nnУютное место с отличной кухней, и баром с множеством авторских коктейлей и настоек nn<b><u>По четвергам скидка на весь алкоголь 20%.</u>nчтобы получить скидку, покажите это сообщение на телефоне</b>nn<i>Отправьте сюда фото из ресторана</i>','https://go.2gis.com/pgjqq','ул. Московская, 2','Ежедневно с 12:00 до 23:00',4,'1','https://www.instagram.com/malevichi_rest?igsh=MzRlODBiNWFlZA==');
/*!40000 ALTER TABLE `bh_bar` ENABLE KEYS */;
UNLOCK TABLES;

